command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERBANN (ZERZAL)
//
// - Bannkegel bis 12 Schritt und 170°
// - Geister erhalten 8 Stufen Furcht
// - Willenskraft um QS × 3 FW erschwert
// - Dauer: QS Stunden
// - GM-Effektbereich direkt über Block 19.8
// - Wirkungsende über Block 6 und Block 11
// ==========================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Zone ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.GabenUI?.Details ||
        !globalThis.DSK?.GabenUI?.GMEffektBereich;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 250));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Zone ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.GabenUI?.Details ||
        !DSK_FW?.GabenUI?.GMEffektBereich
    ) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterbann";
    const ahne = "Zerzal";
    const vollerName = `${gabenName} (${ahne})`;
    const zielEffektName = "Zone - Geisterbann - Furcht";
    const iconBild = DSK_FW.Symbol(ahne);

    DSK_FW.EffektEnde.Register(
        "zerzalGeisterbann",
        vollerName,
        "Die Skratglyphen verblassen, und die Bannzone löst sich auf."
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const getOwners = actor => Object.entries(actor?.ownership || {})
        .filter(([id, lvl]) => lvl === 3 && id !== "default")
        .map(([id]) => id);

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }

        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenMessageId");
        }
    };

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    const safeTestData = typeof testData !== "undefined" ? testData : null;
    const safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor =
        safeTestData?.actor ||
        (safeTestData?.speaker?.token
            ? canvas.tokens.get(safeTestData.speaker.token)?.actor
            : null) ||
        safeActor ||
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag("world", "letzteGabenQS") !== undefined
                ) ||
            game.actors.find(actor =>
                actor.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const whisperTargets = [...new Set([
        ...game.users.filter(user => user.isGM).map(user => user.id),
        ...getOwners(casterActor)
    ])].filter(id => game.users.get(id));

    let qsWert = Number(
        casterActor.getFlag("world", "letzteGabenQS") || 1
    );

    if (safeTestData) {
        qsWert = Number(
            safeTestData?.result?.QL ||
            safeTestData?.qualityStep ||
            qsWert
        );
    }

    const alteMessageId =
        casterActor.getFlag("world", "letzteGabenMessageId");

    if (qsWert <= 0) {
        return ChatMessage.create({
            whisper: whisperTargets,
            speaker: { alias: "System" },
            content: `
                ${DSK_FW.UI.Header(gabenName, iconBild)}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="color:#B30000;text-align:center;">
                        <b>Fehlschlag!</b>
                    </p>
                </div>`
        });
    }

    const casterToken =
        casterActor.getActiveTokens()[0] ||
        canvas.tokens.controlled[0];

    if (!casterToken) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Kein Token des Wirkenden gefunden!"
        );
    }

    // +++ 5 - BANNKEGEL KONFIGURIEREN +++++++++++++++++++++++++

    const einstellungen =
        await foundry.applications.api.DialogV2.wait({
            window: { title: "Bannkegel konfigurieren" },
            position: { width: 420 },

            content: `
                <form>
                    <div style="font-family:'Signika',sans-serif;">
                        ${DSK_FW.UI.Header(vollerName, iconBild)}

                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:.95em;line-height:1.35;margin-bottom:10px;">
                                Lege die Maße für den magischen Bannkegel fest
                                (max. 12 Schritt):
                            </p>

                            <div style="margin-bottom:8px;">
                                <label style="font-weight:bold;font-size:.9em;">
                                    Länge (max. 12 Schritt):
                                </label>

                                <input
                                    type="number"
                                    name="laenge"
                                    value="12"
                                    min="1"
                                    max="12"
                                    style="width:100%;padding:4px;margin-top:4px;"
                                >
                            </div>

                            <div>
                                <label style="font-weight:bold;font-size:.9em;">
                                    Öffnungswinkel (max. 170°):
                                </label>

                                <input
                                    type="number"
                                    name="winkel"
                                    value="60"
                                    min="10"
                                    max="170"
                                    style="width:100%;padding:4px;margin-top:4px;"
                                >
                            </div>
                        </div>
                    </div>
                </form>`,

            buttons: [
                {
                    action: "ok",
                    label: "Weiter",
                    icon: "fas fa-arrow-right",
                    default: true,

                    callback: event => {
                        const data =
                            new FormData(event.target.closest("form"));

                        return {
                            laenge: Math.min(
                                12,
                                Math.max(
                                    1,
                                    Number(data.get("laenge")) || 12
                                )
                            ),

                            winkel: Math.min(
                                170,
                                Math.max(
                                    10,
                                    Number(data.get("winkel")) || 60
                                )
                            )
                        };
                    }
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => null
                }
            ],

            rejectClose: false
        });

    if (!einstellungen) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bann abgebrochen."
        );
    }

    const radiusSchritt = einstellungen.laenge;
    const kegelWinkel = einstellungen.winkel;

    // +++ 6 - BANNKEGEL PLATZIEREN ++++++++++++++++++++++++++++

    const confirmPosition = async () =>
        foundry.applications.api.DialogV2.wait({
            window: { title: "Bannkegel platzieren" },
            position: { width: 420 },

            content: `
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header(vollerName, iconBild)}

                    <div class="dskbox2" style="margin-top:10px;">
                        <p style="font-size:.95em;line-height:1.35;">
                            Verschiebe und drehe den Bannkegel
                            (${radiusSchritt} Schritt, ${kegelWinkel}°)
                            auf der Karte.

                            <br><br>

                            Klicke danach auf
                            <b>Position Bestätigen</b>.
                        </p>
                    </div>
                </div>`,

            buttons: [
                {
                    action: "ok",
                    label: "Position Bestätigen",
                    icon: "fas fa-check",
                    default: true,
                    callback: () => true
                },
                {
                    action: "cancel",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => false
                }
            ],

            rejectClose: false
        });

    ui.notifications.info(
        "Luna sagt 🌙: Platziere und richte den Bannkegel aus."
    );

    const templateData = {
        t: "cone",
        user: game.user.id,
        distance: radiusSchritt,
        direction: 0,
        angle: kegelWinkel,
        x: casterToken.center.x,
        y: casterToken.center.y,
        fillColor: game.user.color || "#000000",
        fillAlpha: 0.15,
        lineThickness: 1,
        hidden: false
    };

    const createdTemplates =
        await canvas.scene.createEmbeddedDocuments(
            "MeasuredTemplate",
            [templateData]
        );

    const templateDoc = createdTemplates[0];

    if (!templateDoc) {
        return ui.notifications.error(
            "Luna sagt 🌙: Der Bannkegel konnte nicht erstellt werden!"
        );
    }

    try {
        canvas.templates.activate();
    } catch (error) {}

    const positionBestaetigt = await confirmPosition();

    try {
        canvas.tokens.activate();
    } catch (error) {}

    if (!positionBestaetigt) {
        await templateDoc.delete();

        return ui.notifications.warn(
            "Luna sagt 🌙: Bann abgebrochen."
        );
    }

    // +++ 7 - WIRKUNGSDATEN +++++++++++++++++++++++++++++++++++

    const dauerStunden = qsWert;
    const erschwernisWillenskraft = qsWert * 3;

    const dauerText =
        `${dauerStunden} Stunde${dauerStunden > 1 ? "n" : ""} ` +
        `<span style="font-weight:300;font-size:.9em;opacity:.8;">` +
        `(${qsWert} QS)</span>`;

    const basisBeschreibung =
        `Das Zerzalkind formt einen magischen Bannkegel ` +
        `(${radiusSchritt} Schritt, ${kegelWinkel}°) ` +
        `aus Skratglyphen.` +
        `<br><br>• Geister im Kegel erleiden 8 Stufen Furcht.` +
        `<br>• Willenskraft um ${erschwernisWillenskraft} FW erschwert.`;

    // +++ 8 - ZIELEFFEKT-DATEN ++++++++++++++++++++++++++++++++

    const effektData = {
        img: iconBild,
        duration: { hours: dauerStunden },

        changes: [
            {
                key: "system.skillModifiers.FW",
                mode: 0,
                value: `Willenskraft -${erschwernisWillenskraft}`,
                priority: 20
            },
            {
                key: "system.status.feared",
                mode: 2,
                value: "8",
                priority: 20
            }
        ],

        statuses: ["feared"],

        description:
            `Erleidet Furcht und ` +
            `-${erschwernisWillenskraft} FW ` +
            `auf Willenskraft im Bannkegel.`,

        flags: {
            dsk: {
                value: 8,
                max: 8
            }
        }
    };

    // +++ 9 - QUELLEFFEKT ++++++++++++++++++++++++++++++++++++++

    const quelleffekt =
        await casterActor.createEmbeddedDocuments(
            "ActiveEffect",
            [{
                name: vollerName,
                type: "base",
                icon: iconBild,
                img: iconBild,
                showIcon: 1,

                duration: {
                    hours: dauerStunden
                },

                description: basisBeschreibung,

                flags: {
                    dsk: {
                        isZoneSource: true,
                        templateId: templateDoc.id,
                        zielEffektName,
                        casterEffektName: vollerName,
                        ahne
                    }
                }
            }]
        );

    if (!quelleffekt?.[0]) {
        await templateDoc.delete();
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Der Geisterbann-Effekt konnte nicht angelegt werden!"
        );
    }

    // +++ 10 - GM-BEREICH DIREKT AUS BLOCK 19.8 +++++++++++++++

    const gmHtml =
        DSK_FW.GabenUI.GMEffektBereich({
            templateId: templateDoc.id,
            zielEffektName,
            ahne,
            effektData
        });

    if (!gmHtml?.includes("dsk-btn-apply")) {
        await quelleffekt[0].delete();
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Der Effekt-anwenden-Button konnte nicht erzeugt werden!"
        );
    }

    // +++ 11 - GEMEINSAME WIRKUNGSKARTE +++++++++++++++++++++++

    const successContent = `
        ${DSK_FW.UI.Header(vollerName, iconBild)}

        <div class="dskbox2" style="margin-top:10px;">
            ${DSK_FW.GabenUI.Details({
                titel: "Gabenwirkung Information",
                inhalt: basisBeschreibung,
                zentriert: true
            })}

            <hr>

            <p style="margin:0 0 4px;text-align:left;">
                <b>Wirkender:</b>
            </p>

            ${DSK_FW.UI.List([casterName])}

            <hr>

            <p style="text-align:center;margin-bottom:0;">
                <b>Wirkungsdauer:</b> ${dauerText}
            </p>

            ${gmHtml}
        </div>`;

    // +++ 12 - KARTE AKTUALISIEREN ++++++++++++++++++++++++++++

    const msg =
        alteMessageId
            ? game.messages.get(alteMessageId)
            : null;

    if (msg) {
        await msg.update({
            content: successContent,
            whisper: [],

            "flags.dsk.gabenAnfrage": true,
            "flags.dsk.gabenName": vollerName,
            "flags.dsk.angewendet": false,
            "flags.dsk.anfragenderUserId": game.user.id
        });
    } else {
        await ChatMessage.create({
            speaker: {
                alias: "System"
            },

            flags: {
                dsk: {
                    gabenAnfrage: true,
                    gabenName: vollerName,
                    angewendet: false,
                    anfragenderUserId: game.user.id
                }
            },

            content: successContent
        });
    }

    // +++ 13 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
